#!/bin/bash
# run_v34.sh <worktree> <lock script> : generates v3_a v3_b v4_a v4_b into src~ with Codex (one image per call, shared lock)
R="$1"; LOCK="$2"
D="$R/Pause/Assets/Art/Worlds/Storm/backdrop_v4~/src~"
COMMON="Use your image generation tool (do not draw procedurally) to paint ONE opaque square image, as large as the tool allows (about 1254x1254). Context: Unity mobile vertical 2D shooter, scrolling ground backdrop for the STORM world, a gas-giant thunderstorm seen straight down (orthographic top-down) from just under the cloud ceiling. Style: alive, colourful hi-res neon pixel art: crisp hand-placed pixel clusters and 1-3 px marks, 5-8 tone painterly ramps per material, hard-edged clusters, no blur, no soft airbrush gradients, no photorealism, no 3D render, no outlines and no white borders. Composition: cloud texture fills every edge, evenly dense edge to edge, shapes continue naturally past every border (no border-dependent shapes, no single centred blob), the central 50% of the width is calmer with lower contrast and fewer bright accents while the outer 25% on each side is the busiest and highest contrast. Palette: deep indigo #14123A to #2A2570, graphite and slate-blue, deep teal #0B3A4A to #1F8A9A in shadows, electric blue #2F6BFF to #6FC3FF, warm amber-peach #FFB347 #FF8A3D #FFD9A0 only as rim light on crests, white-hot lightning #F4F8FF with blue edges. FORBIDDEN: pink, magenta, red, green, lime, brown mud, orange fields, and any horizon, sky, planet, stars, space, water, ocean, waves, foam, ships, structures, UI, text, frame, border, vignette, watermark. The previous Storm sets are a banded diagonal deck with curl scars and a field of cauliflower towers: this one must look like a clearly DIFFERENT PLACE. Look at ./Pause/Assets/Art/Worlds/Storm/backdrop_v4~/preview/after_tiles_v1.jpg and after_tiles_v2.jpg for the palette, pixel density and mood to match (read-only). "
gen() { # name, brief
  local n="$1" b="$2" tries=0
  until [ -f "$D/$n.png" ] || [ $tries -ge 3 ]; do
    "$LOCK" ~/.local/bin/codex exec -m gpt-5.6-luna --skip-git-repo-check -s workspace-write -C "$R" "$COMMON $b Save the final image (copy it from the generated images folder if needed) as $D/$n.png and reply with just the path." > "$D/$n.log" 2>&1
    tries=$((tries+1))
  done
}
V3="NIGHT SIDE variant. Near-black indigo and graphite storm cloud seen from above at night: heavy rolling billows and canyons in very dark ink-indigo, lit from INSIDE by sheet lightning: big soft-edged-but-pixel-stepped blooms of blue-white light glowing up through gaps and under cloud lips, branching lightning veins buried in the canyons, the lit billow edges rimmed in cold blue-white (almost no amber, at most a few dim amber glints). Overall dark (average brightness about 0.2-0.3) but every cloud form stays readable; lightning occupies under 8 percent of the image. "
V4="GUST-FRONT variant. A storm outflow seen from above: huge nested scalloped SHELF ARCS, like successive curved roll-cloud fronts sweeping across the frame in broad overlapping crescents (each arc a long ridge of tight rolled billows with a bright amber-peach rim on its crest edge and a deep teal-indigo shadow trough behind it), arcs stacked like ripples/terraces with calm dark slate cloud between them, a few torn gaps showing deeper darker cloud, thin blue-white lightning threads running along the troughs. Mostly diagonal and curved flow, NOT vertical towers and NOT straight parallel bands. "
gen v3_a "$V3 Variant A: arrangement with a large lit bloom near the upper left and long canyons running diagonally."
gen v3_b "$V3 Variant B: a clearly different arrangement from A: lightning concentrated in a few branching veins low in the frame and smaller billows."
gen v4_a "$V4 Variant A: arcs sweeping from lower left to upper right, widest crescents on the outer edges."
gen v4_b "$V4 Variant B: a clearly different arrangement from A: arcs curving the opposite way (lower right to upper left), tighter and denser."
echo done > "$D/v34_done"
